  WHEN '9dbca987-5d2f-e165-ddf8-50b7967ce7b8' THEN 'c71236ec-c720-e2cf-ac21-28a51cacc54c'::uuid
  WHEN '3fc7d329-c85a-7aac-0095-9e49f9f189f4' THEN 'd02c3281-817c-75fb-0b5f-9e9c69a1c778'::uuid
  WHEN 'e55720c9-03ab-876e-cced-aea59b4c97c0' THEN '87cdc841-4190-10e4-5188-84bc7bbc2ed4'::uuid
  WHEN 'b2304d06-63d7-4dd8-75be-3902de3d4bfa' THEN '8e877b1f-064d-19b6-794a-d8fb79df0901'::uuid
